
# Function to build the initial tableau
BuildInitialTableau = function(A, xNames = NULL)
{
  # Get the number of rows and columns
  row = nrow(A)
  col = ncol(A)

  
  PrimalA = A[1:(row-1), 1:(col-1)]
  PrimalRHS = A[1:(row-1), col]
  objective = A[row, 1:(col-1)]
  
  # Transpose the primal matrix
  InitialA = t(PrimalA)
  
  # Get the number of constraints
  InitialRow = nrow(InitialA)
  
  slack = diag(InitialRow)
  
  # Combine the transposed matrix and slack variables
  tableau = cbind(InitialA, slack)
  
  # Add the Z column
  tableau = cbind(tableau, Z = rep(0, InitialRow))
  
  # Add the Solution column using the objective coefficients
  tableau = cbind(tableau, Solution = as.numeric(objective))
  
  # Set the column names
  if (is.null(xNames)) {
    xNames = paste0("x", 1:InitialRow)
  }
  colnames(tableau) = c(
    paste0("S", 1:(row-1)),
    xNames,
    "Z",
    "Solution"
  )
  
  objRow = c(-PrimalRHS, rep(0, InitialRow), 1, 0)
  
  # Add the objective row to the tableau
  tableau = rbind(tableau, objRow)
  
  # row names for the constraint rows and objective row
  rownames(tableau) = c(paste0("Constraint_", 1:InitialRow), "Objective")
  
  return(tableau)
}



Simplex <- function(tableau,isMax) #Simplex Method function that accept 2 parameters tableau and isMax
{
  
  row = nrow(tableau) #get the number of rows of tableau
  col = ncol(tableau) #get the number of columns of tableau
  
  iteration = 0
  history = list(tableau)
  
  #the loop will continue to run unless the bottom row contains no negative numbers
  while(any(tableau[row, 1:(col-1)] < 0)) 
  {
    #Use a which and minimum built-in r function to know which in the bottom row has the highest negative magnitude.
    pivotColumn = which.min(tableau[row, 1:(col-1)])
    
    #Calculate the test ration using the 
    testRatio = (tableau[1:(row-1), col] /  tableau[1:(row-1), pivotColumn])
    
    #if the test Ratio per Row is less than equal to 0 or infinite(happens if the rightmost column or the solution column is equal to 0)
    testRatio[testRatio <= 0 | is.infinite(testRatio)] = NA
    
    #find which row contain the smallest positive test ratio
    pivotRow = which.min(testRatio)
    
    if (length(pivotRow) == 0 || is.na(pivotRow)) {
      return(list(
        status = "infeasible",
        finalTableau = tableau,
        basicSolution = NULL,
        Z = NA,
        iteration = iteration,
        history = history
      ))
    }
    
    #find the pivot elem
    pivotElem = tableau[pivotRow, pivotColumn]
    
    #Normalized Pivot Row
    nPR = tableau[pivotRow,]/pivotElem
    
    #to access each row
    for (r in 1:row)
    {
      #Check if the current row is not equal to pivot Row
      if(r != pivotRow)
      {
        #update the rows using the formula: R = R - (nPR*C)
        tableau[r, ] = tableau[r, ] -(nPR * tableau[r,pivotColumn])
      }
    }
    
    #update the pivotRow
    tableau[pivotRow, ] = nPR
    
    iteration = iteration +1
    history[[iteration + 1]] = tableau
  }
  
  #copy the tableu to finalTableau
  finalTableau = tableau
  
  #initialize matrix for basicSolution with row 1 and 
  basicSolution = matrix(0, nrow =1, ncol = col-1)
  
  
  # Assign the column name of the tableau to the basicSolution column names
  colnames(basicSolution) = colnames(tableau[, 1:(col-1)])
  
  #if the isMax is True
  if (isMax == TRUE)
  {
    print(" ---------- MAXIMIZATION OUTPUT ---------")
    cat("\n")
    
    for (i in 1:length(history))
    {
      finalTableau = history[[i]]
      basicSolution = matrix(0, nrow = 1, ncol = col-1)
      colnames(basicSolution) = colnames(tableau[, 1:(col-1)])
    
    #to acess each column except the sol column of the tableau
    for (c in 1:(col-1))
    {
      #set the current c to variable column
      column = finalTableau[1:row, c]
      
      #Check if the column contains exactly one non-zero value
      if(sum(column != 0) == 1)
      {
        #get the row of the non-zero value
        rowSolution = which(column != 0)
        #solve for the solution - the value in last column divided by the non-zero value in same row
        solution = finalTableau[rowSolution, col]/finalTableau[rowSolution,c]
      }
      #if the   
      else
      {
        #if the 
        solution = 0
      }
      
      #place the 
      basicSolution[1,c] = solution
    }
      history[[i]] = list(finalTableau = finalTableau, basicSolution = basicSolution)
      
    }
    
  }
  
  #if isMax if False
  else
  {
    print(" ---------- MINIMIZATION OUTPUT ---------") 
    cat("\n")
    
    for (i in 1:length(history))
    {
      finalTableau = history[[i]]
    
    #creating the matrix for basicSolution skipping the value of Z with the Solution val
    basicSolution = matrix(c(finalTableau[row, 1:(col-2)],finalTableau[row,col]), 
                           nrow = 1, ncol = col-1)
    
    # Assign the column name of the tableau to the basicSolution column names
    colnames(basicSolution) = colnames(tableau[, 1:(col-1)])
    history[[i]] = list(finalTableau = finalTableau, basicSolution = basicSolution)
    }
    
  }
  #get the Maximum or Minimum value and store it to Z
  Z = basicSolution[[1, col-1]]
  
  
  #create a list for the output
  output = list(finalTableau = finalTableau, basicSolution = basicSolution, Z = Z, history = history, iteration = iteration) 
  return(output) #returned the list
}


